const CODE_VERSION = "check_availability_v6_weekday_support_final";

const body = $json.body || $json;
const message = body.message || {};

const toolCall =
  message.toolCalls?.[0] ||
  message.toolCallList?.[0] ||
  message.toolWithToolCallList?.[0]?.toolCall ||
  null;

const toolCallId = toolCall?.id || $json.tool_call_id || null;
const toolName =
  toolCall?.function?.name ||
  $json.tool_name ||
  "check_availability";

let args = $json.args || toolCall?.function?.arguments || {};

if (typeof args === "string") {
  try {
    args = JSON.parse(args);
  } catch (error) {
    args = {};
  }
}

const city = String(args.city || $json.city || "").trim().toLowerCase();
const preferredDayRaw = args.preferred_day || $json.preferred_day || "today";
const preferredTimeRaw = args.preferred_time || $json.preferred_time || "";
const currentContext =
  args.current_datetime_context ||
  $json.current_datetime_context ||
  "";

const preferredDay = String(preferredDayRaw).trim().toLowerCase();
const preferredTime = String(preferredTimeRaw).trim().toLowerCase();

const CAL_USERNAME = "mrk-91";
const CAL_EVENT_TYPE_SLUG = "safenest-pest-control";

function getTimeZoneName(cityText) {
  if (cityText.includes("doha")) return "Asia/Qatar";
  return "America/Chicago";
}

function getTimezoneOffset(cityText) {
  if (cityText.includes("doha")) return "+03:00";
  return "-05:00";
}

const calTimeZone = getTimeZoneName(city);
const timezoneOffset = getTimezoneOffset(city);

function pad(num) {
  return String(num).padStart(2, "0");
}

function offsetToMinutes(offset) {
  if (!offset || offset === "Z") return 0;

  const sign = offset.startsWith("-") ? -1 : 1;
  const [hours, minutes] = offset.slice(1).split(":").map(Number);

  return sign * (hours * 60 + minutes);
}

function fromTimestampToLocalParts(timestampMs, offset) {
  const localMs = timestampMs + offsetToMinutes(offset) * 60 * 1000;
  const localDate = new Date(localMs);

  return {
    year: localDate.getUTCFullYear(),
    month: localDate.getUTCMonth(),
    day: localDate.getUTCDate(),
    hour: localDate.getUTCHours(),
    minute: localDate.getUTCMinutes()
  };
}

function parseCurrentContext(text, offset) {
  const value = String(text || "")
    .replace(/[\u200B-\u200D\uFEFF]/g, "")
    .trim();

  if (!value) {
    return {
      parts: fromTimestampToLocalParts(Date.now(), offset),
      warning: "Missing current_datetime_context. Used server time as fallback."
    };
  }

  // ISO format support
  // Example: 2026-05-21T07:35:00+03:00
  const isoMatch = value.match(
    /^(\d{4})-(\d{2})-(\d{2})[T\s](\d{2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?(?:Z|[+-]\d{2}:?\d{2})?$/
  );

  if (isoMatch) {
    return {
      parts: {
        year: Number(isoMatch[1]),
        month: Number(isoMatch[2]) - 1,
        day: Number(isoMatch[3]),
        hour: Number(isoMatch[4]),
        minute: Number(isoMatch[5])
      },
      warning: null
    };
  }

  // Human-readable format support
  // Example: Thursday, May 21, 2026, 07:35 AM
  const humanMatch = value.match(
    /(?:[A-Za-z]+,\s*)?([A-Za-z]+)\s+(\d{1,2}),\s+(\d{4}),\s+(\d{1,2}):(\d{2})\s*(AM|PM)/i
  );

  if (humanMatch) {
    const monthNames = {
      january: 0,
      february: 1,
      march: 2,
      april: 3,
      may: 4,
      june: 5,
      july: 6,
      august: 7,
      september: 8,
      october: 9,
      november: 10,
      december: 11
    };

    const month = monthNames[humanMatch[1].toLowerCase()];
    const day = Number(humanMatch[2]);
    const year = Number(humanMatch[3]);
    let hour = Number(humanMatch[4]);
    const minute = Number(humanMatch[5]);
    const ampm = humanMatch[6].toLowerCase();

    if (ampm === "pm" && hour < 12) hour += 12;
    if (ampm === "am" && hour === 12) hour = 0;

    return {
      parts: { year, month, day, hour, minute },
      warning: null
    };
  }

  return {
    parts: fromTimestampToLocalParts(Date.now(), offset),
    warning: `Could not parse current_datetime_context: ${value}. Used server time as fallback.`
  };
}

function toIso(parts, offset) {
  return `${parts.year}-${pad(parts.month + 1)}-${pad(parts.day)}T${pad(parts.hour)}:${pad(parts.minute)}:00${offset}`;
}

function toUtcIso(localIsoWithOffset) {
  const date = new Date(localIsoWithOffset);

  if (isNaN(date.getTime())) {
    throw new Error("Invalid local ISO date: " + localIsoWithOffset);
  }

  return date.toISOString();
}

function addHours(parts, hours, offset) {
  const timestamp = new Date(toIso(parts, offset)).getTime();
  return fromTimestampToLocalParts(timestamp + hours * 60 * 60 * 1000, offset);
}

function addDays(parts, days, offset) {
  const timestamp = new Date(toIso(parts, offset)).getTime();
  return fromTimestampToLocalParts(timestamp + days * 24 * 60 * 60 * 1000, offset);
}

function getLocalDayOfWeek(parts) {
  // Sunday = 0, Monday = 1, Tuesday = 2, Wednesday = 3, Thursday = 4, Friday = 5, Saturday = 6
  return new Date(Date.UTC(parts.year, parts.month, parts.day)).getUTCDay();
}

function getNextWeekdayInfo(currentDayStart, targetWeekday, preferredDayText, offset) {
  const currentWeekday = getLocalDayOfWeek(currentDayStart);

  let daysToAdd = targetWeekday - currentWeekday;

  if (daysToAdd < 0) {
    daysToAdd += 7;
  }

  if (daysToAdd === 0 && preferredDayText.includes("next")) {
    daysToAdd = 7;
  }

  return {
    requestedDayStart: addDays(currentDayStart, daysToAdd, offset),
    daysToAdd
  };
}

function resolvePreferredDay(preferredDayText, currentDayStart, offset) {
  const dayText = String(preferredDayText || "").trim().toLowerCase();

  if (dayText === "today" || dayText.includes("today")) {
    return {
      requestedDayStart: { ...currentDayStart },
      isTodayRequest: true,
      resolved_day_reason: "today"
    };
  }

  if (dayText.includes("day after tomorrow")) {
    return {
      requestedDayStart: addDays(currentDayStart, 2, offset),
      isTodayRequest: false,
      resolved_day_reason: "day_after_tomorrow"
    };
  }

  if (dayText.includes("tomorrow")) {
    return {
      requestedDayStart: addDays(currentDayStart, 1, offset),
      isTodayRequest: false,
      resolved_day_reason: "tomorrow"
    };
  }

  const isoDateMatch = dayText.match(/\d{4}-\d{2}-\d{2}/);

  if (isoDateMatch) {
    const [year, month, day] = isoDateMatch[0].split("-").map(Number);

    return {
      requestedDayStart: {
        year,
        month: month - 1,
        day,
        hour: 0,
        minute: 0
      },
      isTodayRequest: false,
      resolved_day_reason: "specific_iso_date"
    };
  }

  const weekdays = {
    sunday: 0,
    monday: 1,
    tuesday: 2,
    wednesday: 3,
    thursday: 4,
    friday: 5,
    saturday: 6
  };

  for (const [weekdayName, weekdayNumber] of Object.entries(weekdays)) {
    if (dayText.includes(weekdayName)) {
      const result = getNextWeekdayInfo(
        currentDayStart,
        weekdayNumber,
        dayText,
        offset
      );

      return {
        requestedDayStart: result.requestedDayStart,
        isTodayRequest: result.daysToAdd === 0,
        resolved_day_reason: weekdayName
      };
    }
  }

  return {
    requestedDayStart: { ...currentDayStart },
    isTodayRequest: true,
    resolved_day_reason: "fallback_today"
  };
}

function isWeekend(parts) {
  const dayOfWeek = getLocalDayOfWeek(parts);
  return dayOfWeek === 0 || dayOfWeek === 6;
}

function parsePreferredTime(timeText) {
  const text = String(timeText || "").trim().toLowerCase();

  if (
    text.includes("earliest") ||
    text.includes("next available") ||
    text.includes("any time") ||
    text.includes("anytime")
  ) {
    return null;
  }

  const match = text.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);

  if (!match) return null;

  let hour = Number(match[1]);
  const minute = match[2] ? Number(match[2]) : 0;
  const ampm = match[3]?.toLowerCase();

  if (!ampm && hour >= 1 && hour <= 7) {
    hour += 12;
  }

  if (ampm === "pm" && hour < 12) hour += 12;
  if (ampm === "am" && hour === 12) hour = 0;

  return { hour, minute };
}

function compareDateTime(a, b) {
  const aValue = Number(
    `${a.year}${pad(a.month + 1)}${pad(a.day)}${pad(a.hour)}${pad(a.minute)}`
  );

  const bValue = Number(
    `${b.year}${pad(b.month + 1)}${pad(b.day)}${pad(b.hour)}${pad(b.minute)}`
  );

  if (aValue < bValue) return -1;
  if (aValue > bValue) return 1;
  return 0;
}

const parsedCurrent = parseCurrentContext(currentContext, timezoneOffset);
const current = parsedCurrent.parts;

const earliestAllowed = addHours(current, 4, timezoneOffset);

const currentDayStart = {
  year: current.year,
  month: current.month,
  day: current.day,
  hour: 0,
  minute: 0
};

const resolvedDay = resolvePreferredDay(
  preferredDay,
  currentDayStart,
  timezoneOffset
);

const requestedDayStart = resolvedDay.requestedDayStart;
const isToday = resolvedDay.isTodayRequest;

let rangeStart = { ...requestedDayStart };

let rangeEnd = addDays(requestedDayStart, 3, timezoneOffset);
rangeEnd.hour = 0;
rangeEnd.minute = 0;

if (isToday) {
  rangeStart = earliestAllowed;
}

const parsedPreferredTime = parsePreferredTime(preferredTime);

let preferredDateTime = null;
let preferredTimeIsValid = true;
let preferredTimeInvalidReason = null;

if (parsedPreferredTime) {
  preferredDateTime = {
    year: requestedDayStart.year,
    month: requestedDayStart.month,
    day: requestedDayStart.day,
    hour: parsedPreferredTime.hour,
    minute: parsedPreferredTime.minute
  };

  if (compareDateTime(preferredDateTime, earliestAllowed) < 0) {
    preferredTimeIsValid = false;
    preferredTimeInvalidReason =
      "Preferred time is less than 4 hours from current local time.";
  }

  if (isWeekend(preferredDateTime)) {
    preferredTimeIsValid = false;
    preferredTimeInvalidReason =
      "Preferred day is Saturday or Sunday. Service visits are Monday to Friday only.";
  }
}

const startLocal = toIso(rangeStart, timezoneOffset);
const endLocal = toIso(rangeEnd, timezoneOffset);

const preferredDateTimeLocal = preferredDateTime
  ? toIso(preferredDateTime, timezoneOffset)
  : null;

const calStart = toUtcIso(startLocal);
const calEnd = toUtcIso(endLocal);

const preferredDateTimeUtc = preferredDateTimeLocal
  ? toUtcIso(preferredDateTimeLocal)
  : null;

return [
  {
    json: {
      code_version: CODE_VERSION,

      tool_name: toolName,
      tool_call_id: toolCallId,

      username: CAL_USERNAME,
      eventTypeSlug: CAL_EVENT_TYPE_SLUG,

      start: calStart,
      end: calEnd,
      timeZone: calTimeZone,
      format: "range",

      preferred_datetime_utc: preferredDateTimeUtc,
      preferred_time_is_valid: preferredTimeIsValid,
      preferred_time_invalid_reason: preferredTimeInvalidReason,

      city,
      preferred_day_received: preferredDayRaw,
      preferred_time_received: preferredTimeRaw,
      resolved_day_reason: resolvedDay.resolved_day_reason,

      current_datetime_context_received: currentContext,
      current_datetime_parse_warning: parsedCurrent.warning,

      current_local: toIso(current, timezoneOffset),
      earliest_allowed_local: toIso(earliestAllowed, timezoneOffset),
      requested_day_start_local: toIso(requestedDayStart, timezoneOffset),
      range_start_local: startLocal,
      range_end_local: endLocal,
      preferred_datetime_local: preferredDateTimeLocal
    }
  }
];

const buildData = $("Build Date Range").first().json;
const calResponse = $json;

const toolName = buildData.tool_name || "check_availability";
const toolCallId = buildData.tool_call_id;

const preferredDateTimeUtc = buildData.preferred_datetime_utc;
const timeZone = buildData.timeZone || "Asia/Qatar";

// Cal.com returns slots inside data, grouped by date
const data = calResponse.data || {};

const allSlotsUtc = [];

for (const dateKey of Object.keys(data)) {
  const slots = data[dateKey] || [];

  for (const slot of slots) {
    if (slot.start) {
      allSlotsUtc.push(slot.start);
    }
  }
}

// Compare exact time using timestamp
const desiredTime = preferredDateTimeUtc
  ? new Date(preferredDateTimeUtc).getTime()
  : null;

const reservationSuccess = allSlotsUtc.some(slot => {
  return new Date(slot).getTime() === desiredTime;
});

// Convert UTC slot to Asia/Qatar style: YYYY-MM-DDTHH:MM:SS+03:00
function formatToQatarTime(utcString) {
  const date = new Date(utcString);

  const qatarDate = new Date(date.getTime() + 3 * 60 * 60 * 1000);

  const pad = (num) => String(num).padStart(2, "0");

  const year = qatarDate.getUTCFullYear();
  const month = pad(qatarDate.getUTCMonth() + 1);
  const day = pad(qatarDate.getUTCDate());
  const hour = pad(qatarDate.getUTCHours());
  const minute = pad(qatarDate.getUTCMinutes());
  const second = pad(qatarDate.getUTCSeconds());

  return `${year}-${month}-${day}T${hour}:${minute}:${second}+03:00`;
}

const availableSlots = allSlotsUtc.map(slot => {
  return {
    time: formatToQatarTime(slot)
  };
});

const result = {
  reservation_success: reservationSuccess ? "true" : "false",
  available_slots: availableSlots
};

return [
  {
    json: {
      results: [
        {
          name: toolName,
          toolCallId: toolCallId,
          result: JSON.stringify(result)
        }
      ]
    }
  }
];
